//! Babel-compatible date formatting for the filter `localize_date`.
//!
//! upstream: src/documents/templating/filters.py@v3.4.2 (localize_date) ->
//! babel/dates.py@2.18.0 (format_date, format_datetime, DateTimeFormat, tokenize_pattern,
//! parse_pattern, get_timezone_gmt), babel/core.py (parse_locale). Locale data (CLDR) is generated by
//! `tools/gen_cldr.py` from Babel 2.18.0 into `src/cldr_data.rs`.

use chrono::{Datelike, FixedOffset, NaiveDate, NaiveDateTime, Timelike};

use crate::cldr_data::{DATA, LOCALES};

// Field indices in a data blob (see tools/gen_cldr.py)
const MONTHS: usize = 0; // ctx*36 + width*12 + (m-1); width: abbreviated, wide, narrow
const DAYS: usize = 72; // ctx*28 + width*7 + weekday; width: abbreviated, wide, short, narrow
const ERAS: usize = 128; // width*2 + era
const PERIODS: usize = 134; // width*2 + (am, pm)
const QUARTERS: usize = 140; // ctx*12 + width*4 + (q-1)
const DATE_FORMATS: usize = 164; // full, long, medium, short
const TIME_FORMATS: usize = 168;
const DATETIME_FORMATS: usize = 172;
const GMT_FORMAT: usize = 176;
const FIRST_WEEK_DAY: usize = 177;
const MIN_WEEK_DAYS: usize = 178;
const FIELD_COUNT: usize = 179;

/// Loaded locale data.
pub struct LocaleData {
    fields: Vec<&'static str>,
    first_week_day: i64,
    min_week_days: i64,
}

impl LocaleData {
    fn f(&self, i: usize) -> &'static str {
        self.fields.get(i).copied().unwrap_or("")
    }
}

/// `babel.core.parse_locale` + lookup. `None` = Babel would raise an error.
pub fn load_locale(identifier: &str) -> Option<LocaleData> {
    let mut ident = identifier;
    if let Some((a, _)) = ident.split_once('.') {
        ident = a;
    }
    if let Some((a, _)) = ident.split_once('@') {
        ident = a;
    }
    let mut parts: Vec<&str> = ident.split('_').collect();
    let lang = parts.remove(0).to_lowercase();
    if lang.is_empty() || !lang.chars().all(char::is_alphabetic) {
        return None;
    }
    let mut key = lang;
    // babel `len(parts[0]) == 4 and parts[0].isalpha()` counts characters; title-case char-wise
    // (byte slicing `s[..1]` panicked on a non-ASCII first character).
    if !parts.is_empty() && parts[0].chars().count() == 4 && parts[0].chars().all(char::is_alphabetic) {
        let s = parts.remove(0);
        let mut cs = s.chars();
        let mut t: String = cs.next().map(|c| c.to_uppercase().collect()).unwrap_or_default();
        t.push_str(&cs.as_str().to_lowercase());
        key.push('_');
        key.push_str(&t);
    }
    if !parts.is_empty() {
        if parts[0].len() == 2 && parts[0].chars().all(char::is_alphabetic) {
            key.push('_');
            key.push_str(&parts.remove(0).to_uppercase());
        } else if parts[0].len() == 3 && parts[0].chars().all(|c| c.is_ascii_digit()) {
            key.push('_');
            key.push_str(parts.remove(0));
        }
    }
    if !parts.is_empty() {
        let p = parts[0];
        let first = p.chars().next();
        if (p.len() == 4 && first.is_some_and(|c| c.is_ascii_digit()))
            || (p.chars().count() >= 5 && first.is_some_and(char::is_alphabetic))
        {
            key.push('_');
            key.push_str(&parts.remove(parts.len() - 1).to_uppercase());
        }
    }
    if !parts.is_empty() {
        return None;
    }
    let idx = LOCALES.binary_search_by(|(k, _)| (*k).cmp(key.as_str())).ok()?;
    let blob = DATA.get(LOCALES[idx].1 as usize)?;
    let fields: Vec<&'static str> = blob.split('\u{1f}').collect();
    if fields.len() != FIELD_COUNT {
        return None;
    }
    Some(LocaleData {
        first_week_day: fields[FIRST_WEEK_DAY].parse().unwrap_or(0),
        min_week_days: fields[MIN_WEEK_DAYS].parse().unwrap_or(1),
        fields,
    })
}

/// Value for formatting.
#[derive(Debug, Clone, Copy)]
pub enum DateValue {
    Date(NaiveDate),
    /// `datetime` (Babel treats naive values as UTC).
    DateTime(NaiveDateTime, FixedOffset),
}

impl DateValue {
    fn date(&self) -> NaiveDate {
        match self {
            DateValue::Date(d) => *d,
            DateValue::DateTime(dt, _) => dt.date(),
        }
    }
    fn time(&self) -> Result<(NaiveDateTime, FixedOffset), String> {
        match self {
            DateValue::DateTime(dt, off) => Ok((*dt, *off)),
            DateValue::Date(_) => Err("'datetime.date' object has no attribute 'hour'".into()),
        }
    }
}

enum Tok {
    Chars(String),
    Field(char, usize),
}

fn is_pattern_char(c: char) -> bool {
    "GyYuQqMLwWdDFgEecabBhHKkmsSAzZOvVxX".contains(c)
}

fn allowed_lengths(c: char) -> Option<&'static [usize]> {
    Some(match c {
        'G' | 'Q' | 'q' | 'M' | 'L' | 'a' | 'b' | 'B' | 'Z' | 'x' | 'X' => &[1, 2, 3, 4, 5],
        'w' | 'd' | 'h' | 'H' | 'K' | 'k' | 'm' | 's' => &[1, 2],
        'W' | 'F' => &[1],
        'D' => &[1, 2, 3],
        'E' | 'e' => &[1, 2, 3, 4, 5, 6],
        'c' => &[1, 3, 4, 5, 6],
        'z' | 'V' => &[1, 2, 3, 4],
        'O' | 'v' => &[1, 4],
        _ => return None, // y, Y, u, g, S, A: arbitrary
    })
}

/// `babel.dates.tokenize_pattern`.
fn tokenize(pattern: &str) -> Vec<Tok> {
    let mut result = Vec::new();
    let mut quotebuf: Option<String> = None;
    let mut charbuf = String::new();
    let mut field: Option<(char, usize)> = None;
    let replaced = pattern.replace("''", "\0");
    for ch in replaced.chars() {
        match quotebuf.as_mut() {
            None => {
                if ch == '\'' {
                    if let Some((c, n)) = field.take() {
                        result.push(Tok::Field(c, n));
                    } else if !charbuf.is_empty() {
                        result.push(Tok::Chars(std::mem::take(&mut charbuf).replace('\0', "'")));
                    }
                    quotebuf = Some(String::new());
                } else if is_pattern_char(ch) {
                    if !charbuf.is_empty() {
                        result.push(Tok::Chars(std::mem::take(&mut charbuf).replace('\0', "'")));
                    }
                    match field {
                        Some((c, ref mut n)) if c == ch => *n += 1,
                        _ => {
                            if let Some((c, n)) = field.take() {
                                result.push(Tok::Field(c, n));
                            }
                            field = Some((ch, 1));
                        }
                    }
                } else {
                    if let Some((c, n)) = field.take() {
                        result.push(Tok::Field(c, n));
                    }
                    charbuf.push(ch);
                }
            }
            Some(q) => {
                if ch == '\'' {
                    charbuf.push_str(q);
                    quotebuf = None;
                } else {
                    q.push(ch);
                }
            }
        }
    }
    if let Some((c, n)) = field {
        result.push(Tok::Field(c, n));
    } else if !charbuf.is_empty() {
        result.push(Tok::Chars(charbuf.replace('\0', "'")));
    }
    result
}

fn pad(v: i64, n: usize) -> String {
    // '%0*d' % (n, v)
    if v < 0 {
        format!("-{:0>w$}", -v, w = n.saturating_sub(1))
    } else {
        format!("{v:0>n$}")
    }
}

fn width3(num: usize) -> usize {
    match num.max(3) {
        3 => 0,
        4 => 1,
        _ => 2,
    }
}

struct Fmt<'a> {
    v: DateValue,
    loc: &'a LocaleData,
}

impl Fmt<'_> {
    fn weekday(&self, d: NaiveDate) -> i64 {
        d.weekday().num_days_from_monday() as i64
    }

    fn week_number(&self, day_of_period: i64, day_of_week: Option<i64>) -> i64 {
        let dow = day_of_week.unwrap_or_else(|| self.weekday(self.v.date()));
        let first_day = (dow - self.loc.first_week_day - day_of_period + 1).rem_euclid(7);
        let mut week = (day_of_period + first_day - 1).div_euclid(7);
        if 7 - first_day >= self.loc.min_week_days {
            week += 1;
        }
        week
    }

    fn week_of_year(&self) -> i64 {
        let d = self.v.date();
        let doy = d.ordinal() as i64;
        let mut week = self.week_number(doy, None);
        if week == 0 {
            if let Some(prev) = NaiveDate::from_ymd_opt(d.year() - 1, 12, 31) {
                week = self.week_number(prev.ordinal() as i64, Some(self.weekday(prev)));
            }
        } else if week > 52
            && let Some(next) = NaiveDate::from_ymd_opt(d.year() + 1, 1, 1) {
                let wd = self.weekday(next);
                if self.week_number(1, Some(wd)) == 1
                    && 32 - (wd - self.loc.first_week_day).rem_euclid(7) <= d.day() as i64
                {
                    week = 1;
                }
            }
        week
    }

    fn gmt(&self, off: FixedOffset, width: &str, return_z: bool) -> String {
        let secs = off.local_minus_utc() as i64;
        let hours = secs.div_euclid(3600);
        let rest = secs.rem_euclid(3600);
        let fmt_h = |h: i64| if h < 0 { format!("-{:02}", -h) } else { format!("+{h:02}") };
        if return_z && hours == 0 && rest == 0 {
            return "Z".into();
        }
        if rest == 0 && width == "iso8601_short" {
            return fmt_h(hours);
        }
        let m = rest / 60;
        match width {
            "short" | "iso8601_short" => format!("{}{:02}", fmt_h(hours), m),
            "iso8601" => format!("{}:{:02}", fmt_h(hours), m),
            _ => self.loc.f(GMT_FORMAT).replace("%s", &format!("{}:{:02}", fmt_h(hours), m)),
        }
    }

    fn field(&self, c: char, num: usize) -> Result<String, String> {
        let d = self.v.date();
        Ok(match c {
            'G' => self.loc.f(ERAS + width3(num) * 2 + 1).to_string(),
            'y' | 'Y' | 'u' => {
                let mut value = d.year() as i64;
                if c == 'Y' {
                    let wk = self.week_of_year();
                    if d.month() == 1 && d.day() < 7 && wk >= 52 {
                        value -= 1;
                    } else if d.month() == 12 && d.day() > 25 && wk <= 2 {
                        value += 1;
                    }
                }
                let s = pad(value, num);
                if num == 2 {
                    s.chars().rev().take(2).collect::<Vec<_>>().into_iter().rev().collect()
                } else {
                    s
                }
            }
            'Q' | 'q' => {
                let q = (d.month0() / 3) as usize;
                if num <= 2 {
                    pad(q as i64 + 1, num)
                } else {
                    let ctx = if c == 'Q' { 0 } else { 1 };
                    self.loc.f(QUARTERS + ctx * 12 + width3(num) * 4 + q).to_string()
                }
            }
            'M' | 'L' => {
                if num <= 2 {
                    pad(d.month() as i64, num)
                } else {
                    let ctx = if c == 'M' { 0 } else { 1 };
                    self.loc.f(MONTHS + ctx * 36 + width3(num) * 12 + d.month0() as usize).to_string()
                }
            }
            'w' => pad(self.week_of_year(), num),
            'W' => self.week_number(d.day() as i64, None).to_string(),
            'd' => pad(d.day() as i64, num),
            'D' => pad(d.ordinal() as i64, num),
            'F' => ((d.day() - 1) / 7 + 1).to_string(),
            'E' | 'e' | 'c' => {
                let mut num = num;
                if num < 3 {
                    if c.is_lowercase() {
                        let value = 7 - self.loc.first_week_day + self.weekday(d);
                        return Ok(pad(value.rem_euclid(7) + 1, num));
                    }
                    num = 3;
                }
                let width = match num {
                    3 => 0,
                    4 => 1,
                    5 => 3,
                    _ => 2,
                };
                let ctx = if c == 'c' { 1 } else { 0 };
                self.loc.f(DAYS + ctx * 28 + width * 7 + self.weekday(d) as usize).to_string()
            }
            'a' => {
                let (t, _) = self.v.time()?;
                let pm = usize::from(t.hour() >= 12);
                self.loc.f(PERIODS + width3(num) * 2 + pm).to_string()
            }
            'b' | 'B' => return Err(format!("Unsupported date/time field {c:?} (day periods)")),
            'h' | 'H' | 'K' | 'k' => {
                let (t, _) = self.v.time()?;
                let h = t.hour() as i64;
                let v = match c {
                    'h' => {
                        if h % 12 == 0 {
                            12
                        } else {
                            h % 12
                        }
                    }
                    'H' => h,
                    'K' => h % 12,
                    _ => {
                        if h == 0 {
                            24
                        } else {
                            h
                        }
                    }
                };
                pad(v, num)
            }
            'm' => pad(self.v.time()?.0.minute() as i64, num),
            's' => pad(self.v.time()?.0.second() as i64, num),
            'S' => {
                let us = (self.v.time()?.0.nanosecond() / 1000) as f64;
                let p = 10f64.powi(num as i32);
                let rounded = ((us / 1_000_000.0) * p).round_ties_even() / p;
                pad((rounded * p) as i64, num)
            }
            'A' => {
                let t = self.v.time()?.0;
                let ms = (t.nanosecond() / 1_000_000) as i64
                    + t.second() as i64 * 1000
                    + t.minute() as i64 * 60000
                    + t.hour() as i64 * 3_600_000;
                pad(ms, num)
            }
            'z' | 'Z' | 'O' | 'v' | 'V' | 'x' | 'X' => {
                let (_, off) = self.v.time()?;
                let width = match num.max(3) {
                    3 => "short",
                    4 => "long",
                    _ => "iso8601",
                };
                match c {
                    'z' | 'v' | 'V' => {
                        // Zone names: only UTC is named like Babel (see Known differences)
                        if off.local_minus_utc() == 0 && num <= 3 {
                            "UTC".into()
                        } else {
                            self.gmt(off, "long", false)
                        }
                    }
                    'Z' => self.gmt(off, width, num == 5),
                    'O' => {
                        if num == 4 {
                            self.gmt(off, width, false)
                        } else {
                            "None".into()
                        }
                    }
                    _ => {
                        let w = match num {
                            1 => "iso8601_short",
                            2 | 4 => "short",
                            _ => "iso8601",
                        };
                        self.gmt(off, w, c == 'X')
                    }
                }
            }
            _ => return Err(format!("Unsupported date/time field {c:?}")),
        })
    }

    fn apply(&self, pattern: &str) -> Result<String, String> {
        let toks = tokenize(pattern);
        // parse_pattern checks the lengths before formatting
        for t in &toks {
            if let Tok::Field(c, n) = t
                && let Some(allowed) = allowed_lengths(*c)
                    && !allowed.contains(n) {
                        return Err(format!(
                            "Invalid length for field: {}",
                            crate::pystr::py_str_repr(&c.to_string().repeat(*n))
                        ));
                    }
        }
        let mut out = String::new();
        for t in toks {
            match t {
                Tok::Chars(s) => out.push_str(&s),
                Tok::Field(c, n) => out.push_str(&self.field(c, n)?),
            }
        }
        Ok(out)
    }
}

fn preset_index(format: &str) -> Option<usize> {
    match format {
        "full" => Some(0),
        "long" => Some(1),
        "medium" => Some(2),
        "short" => Some(3),
        _ => None,
    }
}

/// `babel.dates.format_date` or `format_datetime` (depending on value type, like `localize_date`).
pub fn format_localized(value: DateValue, format: &str, loc: &LocaleData) -> Result<String, String> {
    match value {
        DateValue::Date(d) => {
            let pattern = match preset_index(format) {
                Some(i) => loc.f(DATE_FORMATS + i),
                None => format,
            };
            Fmt { v: DateValue::Date(d), loc }.apply(pattern)
        }
        DateValue::DateTime(..) => {
            let fmt = Fmt { v: value, loc };
            match preset_index(format) {
                Some(i) => {
                    let time = fmt.apply(loc.f(TIME_FORMATS + i))?;
                    let date = Fmt { v: DateValue::Date(value.date()), loc }.apply(loc.f(DATE_FORMATS + i))?;
                    Ok(loc
                        .f(DATETIME_FORMATS + i)
                        .replace('\'', "")
                        .replace("{0}", &time)
                        .replace("{1}", &date))
                }
                None => fmt.apply(format),
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Byte-slicing regression: a 4-byte non-ASCII "script" part must not panic.
    #[test]
    fn load_locale_non_ascii_script_no_panic() {
        let _ = load_locale("en_\u{e4}b");
        let _ = load_locale("en_\u{e4}bcd");
        assert!(load_locale("en_US").is_some());
    }

    fn d() -> DateValue {
        DateValue::Date(NaiveDate::from_ymd_opt(2023, 10, 26).unwrap())
    }
    fn dt() -> DateValue {
        let n = NaiveDate::from_ymd_opt(2023, 10, 26).unwrap().and_hms_opt(14, 30, 5).unwrap();
        DateValue::DateTime(n, FixedOffset::east_opt(0).unwrap())
    }
    fn f(v: DateValue, p: &str, l: &str) -> String {
        format_localized(v, p, &load_locale(l).unwrap()).unwrap()
    }

    // upstream: src/documents/tests/test_filters.py (TestDateLocalization)
    #[test]
    fn date_objects() {
        assert_eq!(f(d(), "EEEE, MMM d, yyyy", "en_US"), "Thursday, Oct 26, 2023");
        assert_eq!(f(d(), "dd.MM.yyyy", "de_DE"), "26.10.2023");
        assert_eq!(f(d(), "EEEE", "de_DE"), "Donnerstag");
        assert_eq!(f(d(), "MMMM", "de_DE"), "Oktober");
        assert_eq!(f(d(), "EEEE", "fr_FR"), "jeudi");
        assert_eq!(f(d(), "MMMM", "fr_FR"), "octobre");
    }

    #[test]
    fn datetime_objects() {
        assert_eq!(f(dt(), "yyyy.MM.dd G 'at' HH:mm:ss zzz", "en_US"), "2023.10.26 AD at 14:30:05 UTC");
        assert_eq!(f(dt(), "dd.MM.yyyy", "fr_FR"), "26.10.2023");
        assert_eq!(f(dt(), "EEEE", "es_ES"), "jueves");
        assert_eq!(f(dt(), "MMMM", "es_ES"), "octubre");
        assert_eq!(f(dt(), "EEEE", "it_IT"), "giovedì");
        assert_eq!(f(dt(), "MMMM", "it_IT"), "ottobre");
    }

    #[test]
    fn invalid_locale() {
        assert!(load_locale("invalid_locale_code").is_none());
        assert!(load_locale("de-DE").is_none());
        assert!(load_locale("DE_de").is_some());
        assert!(load_locale("en_US.UTF-8").is_some());
    }

    #[test]
    fn presets() {
        assert_eq!(f(d(), "medium", "de_DE"), "26.10.2023");
        assert_eq!(f(d(), "long", "en_US"), "October 26, 2023");
        assert_eq!(f(dt(), "short", "en_US"), "10/26/23, 2:30\u{202f}PM");
    }

    #[test]
    fn invalid_field_length() {
        let l = load_locale("en").unwrap();
        assert_eq!(format_localized(d(), "dddd", &l).unwrap_err(), "Invalid length for field: 'dddd'");
        assert!(format_localized(d(), "HH", &l).is_err());
    }
}
